// Wrap a payload into a frame; returns bytes written (0 if out is too small).
inline size_t encodeFrame(MsgType type, const uint8_t* payload, size_t n, uint8_t* out, size_t cap) {
  if (n > kMaxPayload || cap < n + kFrameOverhead) return 0;
  out[0] = kSync0;
  out[1] = kSync1;
  out[2] = static_cast<uint8_t>(n);
  out[3] = static_cast<uint8_t>(n >> 8);
  out[4] = static_cast<uint8_t>(type);
  if (n) std::memcpy(out + 5, payload, n);
  const uint16_t c = crc16(out + 2, n + 3);
  out[5 + n] = static_cast<uint8_t>(c);
  out[6 + n] = static_cast<uint8_t>(c >> 8);
  return n + kFrameOverhead;
}

template <typename Msg>
size_t encode(const Msg& m, uint8_t* out, size_t cap) {
  uint8_t buf[kMaxPayload];
  const size_t n = m.pack(buf);
  return encodeFrame(Msg::kType, buf, n, out, cap);
}

